class Countdown:
    def __init__(self, start):
        self.current = start

    def __iter__(self):
        return self

    def __next__(self):
        if self.current <= 0:
            raise StopIteration
        value = self.current
        self.current -= 1
        return value


print(list(Countdown(3)))
print(sum(Countdown(4)))

nums = iter([1, 2])
print(next(nums), next(nums))

try:
    next(nums)
except StopIteration:
    print("耗尽")

